package dao;import model.*;import java.sql.*;
/** Điều phối transaction, dùng chung Connection như kịch bản V3. Thanh toán chỉ mô phỏng. */
public class Checkout5 extends DAO5{public Checkout5(Connection c){super(c);}public Order5 complete(Order5 draft,String method)throws Exception{con.setAutoCommit(false);try{try(PreparedStatement p=stmt("SELECT TrangThai FROM tblOrder5 WHERE id=? FOR UPDATE",draft.getId());ResultSet r=p.executeQuery()){if(!r.next())throw new IllegalArgumentException("Đơn không tồn tại");if("DA_THANH_TOAN".equals(r.getString(1))){con.commit();return new OrderDAO5(con).get(draft.getId(),draft.getThanhVien().getId());}}
// Khóa suất chiếu để các lần thanh toán cùng suất được kiểm tra tuần tự.
int sid=draft.getVe()[0].getSuatChieu().getId();try(PreparedStatement p=stmt("SELECT id FROM tblScreening5 WHERE id=? FOR UPDATE",sid);ResultSet r=p.executeQuery()){if(!r.next())throw new IllegalArgumentException("Suất không tồn tại");}
TicketDAO5 td=new TicketDAO5(con);Seat5[] gs=java.util.Arrays.stream(draft.getVe()).map(Ticket5::getGhe).toArray(Seat5[]::new);draft.setVe(td.prepareTickets(new ScreeningDAO5(con).get(sid),gs));if(draft.getThe()!=null)new MembershipCardDAO5(con).getValidCard(draft.getThe().getMaThe());Payment5 payment=new PaymentDAO5(con).pay(draft,method);if(!"SUCCESS".equals(payment.getTrangThai())){con.commit();throw new IllegalArgumentException("Thanh toán mô phỏng thất bại. Bạn có thể thử lại.");}OrderDAO5 od=new OrderDAO5(con);od.confirmPayment(draft,payment);td.issueTickets(draft);od.createReceipt(draft);con.commit();return od.get(draft.getId(),draft.getThanhVien().getId());}catch(Exception e){con.rollback();draft.setTrangThai("CHO_THANH_TOAN");throw e;}finally{con.setAutoCommit(true);}}}
